package cartcase

import (
	"os"
	"strconv"
	"strings"
	"testing"
)

func TestCanAdd(t *testing.T) {
	data, _ := os.ReadFile("max_items.txt")
	limit, _ := strconv.Atoi(strings.TrimSpace(string(data)))
	if !CanAdd(limit) {
		t.Fatalf("CanAdd(%d) should be true", limit)
	}
	if CanAdd(limit + 1) {
		t.Fatalf("CanAdd(%d) should be false (stale limit not updated)", limit+1)
	}
}

